#!/usr/bin/env python3
import json, subprocess, re, html as html_escape
from pathlib import Path

root = Path(__file__).parent
chunks = [root / "voice_1.mp3", root / "voice_2.mp3"]
durations = []
for p in chunks:
    raw = subprocess.check_output(["ffprobe","-v","error","-show_entries","format=duration","-of","json",str(p)], text=True)
    durations.append(float(json.loads(raw)["format"]["duration"]))
total = sum(durations)
if not 45 <= total <= 75:
    raise SystemExit(f"Preview duration {total:.2f}s outside 45–75s")

# These are the exact two spoken paragraphs generated by the preview workflow.
sections = [
"You would think saving your first one thousand dollars should be simple. Just spend a little less, put the rest away, and wait. But if you've ever tried it, you know it can feel almost impossible. You get paid, you make a plan, and somehow, by the end of the month, that thousand dollars is still nowhere in sight. Here's the part most people miss: the first thousand isn't just a money goal. It's a battle against timing, habits, and surprise expenses.",
"Picture payday. Your account balance jumps, and for a moment, it feels like you're finally ahead. Then rent is due. Your car needs gas. Groceries, phone bill, insurance, utilities, and minimum payments all arrive. Before you buy anything fun, a big part of that paycheck already belongs somewhere else. This is why a budget can feel discouraging: you're not starting with a pile of free money. You're starting with income that already has assignments."
]
beat_cards, beat_css = [], []
elapsed, beat_no = 0.0, 0
for section_no, (paragraph, section_duration) in enumerate(zip(sections, durations), 1):
    words = paragraph.split()
    target_count = max(1, round(section_duration / 3.0))
    per_beat = max(5, (len(words) + target_count - 1) // target_count)
    phrases = [" ".join(words[i:i+per_beat]) for i in range(0, len(words), per_beat)]
    beat_duration = section_duration / len(phrases)
    for phrase in phrases:
        beat_no += 1
        lower = phrase.lower()
        if any(x in lower for x in ["payday", "paid", "account balance", "income"]):
            label, symbol, kind = "PAYDAY / MONEY IN", "$", "cash"
        elif any(x in lower for x in ["rent", "phone bill", "insurance", "utilities", "minimum payments"]):
            label, symbol, kind = "BILLS / MONEY OUT", "−$", "receipt"
        elif any(x in lower for x in ["gas", "car"]):
            label, symbol, kind = "EVERYDAY COSTS", "↗", "gauge"
        elif any(x in lower for x in ["groceries", "buy", "spend", "spending"]):
            label, symbol, kind = "DAILY SPENDING", "−$", "wallet"
        elif any(x in lower for x in ["surprise", "timing", "habits", "impossible"]):
            label, symbol, kind = "THE SAVING CHALLENGE", "?", "alert"
        elif any(x in lower for x in ["thousand", "1,000", "money goal"]):
            label, symbol, kind = "THE FIRST $1,000", "$1K", "target"
        else:
            label, symbol, kind = "BUILD THE FIRST BUFFER", "$", "cash"
        start, end = elapsed, elapsed + beat_duration
        p0, p1 = start/total*100, min(start+0.16,end)/total*100
        p2, p3 = max(start+0.16,end-0.16)/total*100, end/total*100
        beat_cards.append(
            f'<div class="beat {kind}" style="animation:beat{beat_no} {total:.3f}s linear both">'
            f'<div class="beat-label">{label}</div><div class="beat-copy">{html_escape.escape(phrase)}</div>'
            f'<div class="beat-object"><div class="object-mark">{symbol}</div><div class="object-lines"><i></i><i></i><i></i></div></div>'
            f'<div class="beat-foot">THE FIRST $1,000  •  ONE STEP AT A TIME</div><div class="beat-progress"><i></i></div></div>'
        )
        beat_css.append(f'@keyframes beat{beat_no}{{0%,{p0:.4f}%{{opacity:0;transform:translateY(30px) scale(.97)}}{p1:.4f}%,{p2:.4f}%{{opacity:1;transform:translateY(0) scale(1)}}{p3:.4f}%,100%{{opacity:0;transform:translateY(-20px) scale(1.01)}}}}')
        elapsed = end

html_path = root / "index.html"
html = html_path.read_text()
html = re.sub(r'data-duration="[^"]+"', f'data-duration="{total:.3f}"', html, count=1)
html = re.sub(r'animation:progress 60s linear both', f'animation:progress {total:.3f}s linear both', html)
html = html.replace('<audio id="narration"', '<div id="beat-stage" data-layout-ignore>' + ''.join(beat_cards) + '</div>\n<audio id="narration"', 1)
styles = """
#beat-stage{position:absolute;left:1010px;top:195px;width:820px;height:700px;z-index:30;pointer-events:none}
.beat{position:absolute;inset:0;border:2px solid #58718c;border-radius:30px;background:linear-gradient(145deg,#172f49f7,#0b192bf7);box-shadow:0 28px 70px #000b;padding:58px 62px;overflow:hidden;opacity:0}
.beat:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 78% 24%,#22d3ee25,transparent 42%)}
.beat-label{position:relative;font-size:22px;letter-spacing:3px;font-weight:950;color:#67e8f9}
.beat-copy{position:relative;margin-top:28px;max-width:680px;font-size:43px;line-height:1.12;font-weight:1000;color:#f8fafc;min-height:180px}
.beat-object{position:absolute;right:62px;bottom:100px;width:245px;height:155px;display:flex;align-items:center;justify-content:center}
.object-mark{width:132px;height:132px;border:7px solid #fde68a;border-radius:28px;background:linear-gradient(145deg,#1c6048,#0d352a);display:grid;place-items:center;font-size:58px;font-weight:1000;color:#bbf7d0;box-shadow:0 18px 35px #0008;transform:rotate(-8deg);animation:objectFloat 2.2s ease-in-out infinite alternate}
.receipt .object-mark{border-radius:8px;background:#e2e8f0;color:#0f172a;border-color:#94a3b8}
.gauge .object-mark{border-radius:50%;background:linear-gradient(145deg,#164e63,#082f49);border-color:#67e8f9;color:#a5f3fc}
.wallet .object-mark{background:linear-gradient(145deg,#713f12,#422006);border-color:#fbbf24;color:#fde68a}
.alert .object-mark{border-radius:50%;background:linear-gradient(145deg,#7f1d1d,#450a0a);border-color:#fb7185;color:#fecdd3}
.target .object-mark{border-radius:50%;background:linear-gradient(145deg,#14532d,#052e16);border-color:#4ade80;color:#bbf7d0}
.object-lines{position:absolute;left:0;bottom:10px;display:flex;gap:7px;align-items:end}
.object-lines i{display:block;width:24px;border-radius:8px;background:linear-gradient(#22d3ee,#4ade80);height:45px;animation:bars 1.2s ease-in-out infinite alternate}
.object-lines i:nth-child(2){height:80px;animation-delay:.2s}.object-lines i:nth-child(3){height:60px;animation-delay:.4s}
.beat-foot{position:absolute;left:62px;bottom:64px;font-size:17px;letter-spacing:3px;font-weight:900;color:#9fb8d1}
.beat-progress{position:absolute;left:62px;right:62px;bottom:34px;height:7px;border-radius:8px;background:#31465f;overflow:hidden}
.beat-progress i{display:block;width:100%;height:100%;background:linear-gradient(90deg,#22d3ee,#4ade80);transform-origin:left;animation:fillBar 2.7s ease-out both}
@keyframes objectFloat{to{transform:translateY(-14px) rotate(5deg)}}@keyframes bars{to{transform:scaleY(.65);transform-origin:bottom}}
@keyframes fillBar{from{transform:scaleX(.02)}to{transform:scaleX(1)}}
.scene .panel{opacity:0!important}
""" + "\n".join(beat_css) + "\n"
html = html.replace('</style>', styles + '</style>', 1)
if 'window.__timelines.main' not in html:
    html = html.replace('</body>', '<script src="https://cdn.jsdelivr.net/npm/gsap@3/dist/gsap.min.js"></script><script>window.__timelines=window.__timelines||{};const tl=gsap.timeline({paused:true});tl.to({}, {duration:'+f'{total:.3f}'+'});window.__timelines.main=tl;</script></body>')
html_path.write_text(html)
print(f"PREVIEW_VISUAL_BEATS={beat_no} AVG_BEAT_SECONDS={total/beat_no:.2f}")
print("PREVIEW_VOICE_DURATIONS=" + ",".join(f"{x:.2f}" for x in durations))
print(f"PREVIEW_DURATION={total:.2f}s")
